begin;
select plan(35);

select is((select count(*) from information_schema.tables where table_schema = 'app' and table_name in ('academic_levels','academic_semesters','academic_modules','academic_module_aliases','instructors','instructor_brand_assignments','brand_courses','course_instructor_assignments')), 8::bigint, 'M2A creates exactly eight scoped tables.');
select is((select count(*) from information_schema.tables where table_schema = 'app' and table_type = 'BASE TABLE' and table_name in ('educational_brands','app_users','brand_memberships','student_profiles','admin_profiles','admin_permissions','admin_roles','admin_role_permissions','platform_admin_role_assignments','admin_command_receipts','admin_audit_events','academic_levels','academic_semesters','academic_modules','academic_module_aliases','instructors','instructor_brand_assignments','brand_courses','course_instructor_assignments')), 19::bigint, 'M1, M4A, and M2A scoped clean chain has nineteen tables.');
select is((select count(*) from information_schema.columns where table_schema='app' and table_name='academic_modules' and column_name='academic_module_id'), 0::bigint, 'AcademicModule has no brand or offering reference.');
select is((select count(*) from information_schema.columns where table_schema='app' and table_name='academic_modules' and column_name='brand_id'), 0::bigint, 'AcademicModule has no brand id.');
select is((select count(*) from information_schema.columns where table_schema='app' and table_name='instructors' and column_name in ('email','phone','specialty','department','title','avatar_url','auth_user_id')), 0::bigint, 'Instructor identity stores no unapproved metadata.');
select is((select count(*) from app.educational_brands where code = 'buc'), 0::bigint, 'BUC is not a commercial brand.');
select is((select count(*) from app.academic_levels), 0::bigint, 'No M2A rows exist without the seed.');
select is((select count(*) from app.academic_semesters), 0::bigint, 'No semester rows exist without the seed.');
select is((select count(*) from app.academic_modules), 0::bigint, 'No module rows exist without the seed.');
select is((select count(*) from app.academic_module_aliases), 0::bigint, 'No alias rows exist without the seed.');
select is((select count(*) from app.instructors), 0::bigint, 'No instructor rows exist without the seed.');
select is((select count(*) from app.instructor_brand_assignments), 0::bigint, 'No teaching scope rows exist without the seed.');
select is((select count(*) from app.brand_courses), 0::bigint, 'No commercial course rows exist without the seed.');
select is((select count(*) from app.course_instructor_assignments), 0::bigint, 'No course assignment rows exist without the seed.');

insert into app.academic_institutions (id, code, display_name, slug) values ('70000000-0000-4000-8000-000000000012','fixture-university','Fixture University','fixture-university');
insert into app.academic_levels (id, academic_institution_id, level_number, display_title, sort_order) values ('70000000-0000-4000-8000-000000000001','70000000-0000-4000-8000-000000000012',1,'Fixture Level',1);
select throws_ok($$insert into app.academic_levels (level_number,display_title,sort_order) values (0,'Bad',1)$$, '23514', null, 'Level number must be positive.');
select throws_ok($$insert into app.academic_levels (level_number,display_title,sort_order) values (2,'Bad',0)$$, '23514', null, 'Level sort order must be positive.');
select throws_ok($$insert into app.academic_levels (level_number,display_title,sort_order,status) values (2,'Bad',1,'invalid')$$, '23514', null, 'Level status is constrained.');
insert into app.academic_semesters (id, academic_level_id, semester_number, display_title, sort_order) values ('70000000-0000-4000-8000-000000000002','70000000-0000-4000-8000-000000000001',1,'Fixture Semester',1);
select throws_ok($$insert into app.academic_semesters (academic_level_id,semester_number,display_title,sort_order) values ('70000000-0000-4000-8000-000000000001',1,'Duplicate',2)$$, '23505', null, 'Semester number is unique inside its level.');
insert into app.academic_levels (id, academic_institution_id, level_number, display_title, sort_order) values ('70000000-0000-4000-8000-000000000003','70000000-0000-4000-8000-000000000012',2,'Fixture Level Two',2);
select lives_ok($$insert into app.academic_semesters (academic_level_id,semester_number,display_title,sort_order) values ('70000000-0000-4000-8000-000000000003',1,'Same Number Other Level',1)$$, 'Semester number may repeat in a different level.');
insert into app.academic_modules (id, academic_semester_id, academic_institution_id, code, source_display_label, sort_order) values ('70000000-0000-4000-8000-000000000004','70000000-0000-4000-8000-000000000002','70000000-0000-4000-8000-000000000012','9001 TST','9001 TST',1);
select throws_ok($$insert into app.academic_modules (academic_semester_id,academic_institution_id,code,source_display_label,sort_order) values ('70000000-0000-4000-8000-000000000002','70000000-0000-4000-8000-000000000012','9001 tst','Duplicate',2)$$, '23505', null, 'Module normalized code is unique inside an institution.');
select throws_ok($$insert into app.academic_modules (academic_semester_id,code,source_display_label,sort_order,review_status) values ('70000000-0000-4000-8000-000000000002','9002 TST','Bad',1,'invalid')$$, '23514', null, 'Module review status is constrained.');
select throws_ok($$insert into app.academic_module_aliases (academic_module_id,alias_value,status) values ('70000000-0000-4000-8000-000000000004','Alias','invalid')$$, '23514', null, 'Alias status is constrained.');
insert into app.instructors (id, code, display_name) values ('70000000-0000-4000-8000-000000000005','INS-FIXTURE','اسم تجريبي');
select throws_ok($$insert into app.instructors (code,display_name) values ('INS-FIXTURE','Other')$$, '23505', null, 'Instructor code is unique.');
select is((select display_name from app.instructors where id='70000000-0000-4000-8000-000000000005'), 'اسم تجريبي', 'Unicode Instructor display name is accepted.');
insert into app.educational_brands (id,code,name,slug) values ('70000000-0000-4000-8000-000000000006','fixture-medway','Fixture Medway','fixture-medway'),('70000000-0000-4000-8000-000000000007','fixture-elite','Fixture Elite','fixture-elite');
insert into app.instructor_brand_assignments (id,instructor_id,brand_id) values ('70000000-0000-4000-8000-000000000008','70000000-0000-4000-8000-000000000005','70000000-0000-4000-8000-000000000006'),('70000000-0000-4000-8000-000000000009','70000000-0000-4000-8000-000000000005','70000000-0000-4000-8000-000000000007');
select throws_ok($$insert into app.instructor_brand_assignments (instructor_id,brand_id) values ('70000000-0000-4000-8000-000000000005','70000000-0000-4000-8000-000000000006')$$, '23505', null, 'Instructor teaching scope is unique per brand.');
insert into app.brand_courses (id,brand_id,academic_institution_id,academic_module_id,code,title,classification) values ('70000000-0000-4000-8000-000000000010','70000000-0000-4000-8000-000000000006','70000000-0000-4000-8000-000000000012','70000000-0000-4000-8000-000000000004','MED-9001','Fixture Medway Course','academic_module_offering'),('70000000-0000-4000-8000-000000000011','70000000-0000-4000-8000-000000000007','70000000-0000-4000-8000-000000000012','70000000-0000-4000-8000-000000000004','ELI-9001','Fixture Elite Course','academic_module_offering');
select throws_ok($$insert into app.brand_courses (brand_id,code,title,classification) values ('70000000-0000-4000-8000-000000000006','BAD','Bad','academic_module_offering')$$, '23514', null, 'Academic offering requires an academic module.');
select lives_ok($$insert into app.course_instructor_assignments (brand_id,course_id,instructor_brand_assignment_id) values ('70000000-0000-4000-8000-000000000006','70000000-0000-4000-8000-000000000010','70000000-0000-4000-8000-000000000008')$$, 'Matching same-brand teaching assignment is accepted.');
select throws_ok($$insert into app.course_instructor_assignments (brand_id,course_id,instructor_brand_assignment_id) values ('70000000-0000-4000-8000-000000000006','70000000-0000-4000-8000-000000000010','70000000-0000-4000-8000-000000000009')$$, '23503', null, 'Medway course rejects Elite-only instructor scope.');
select throws_ok($$insert into app.course_instructor_assignments (brand_id,course_id,instructor_brand_assignment_id) values ('70000000-0000-4000-8000-000000000007','70000000-0000-4000-8000-000000000011','70000000-0000-4000-8000-000000000008')$$, '23503', null, 'Elite course rejects Medway-only instructor scope.');
select throws_ok($$insert into app.course_instructor_assignments (brand_id,course_id,instructor_brand_assignment_id) values ('70000000-0000-4000-8000-000000000006','70000000-0000-4000-8000-000000000010','70000000-0000-4000-8000-000000000008')$$, '23505', null, 'Duplicate course and Instructor scope assignment is rejected.');
select is((with f as (select c.conrelid, c.conkey from pg_constraint c join pg_class rel on rel.oid=c.conrelid join pg_namespace ns on ns.oid=rel.relnamespace where c.contype='f' and ns.nspname='app' and rel.relname in ('academic_levels','academic_semesters','academic_modules','academic_module_aliases','instructors','instructor_brand_assignments','brand_courses','course_instructor_assignments')), u as (select f.* from f where not exists (select 1 from pg_index i where i.indrelid=f.conrelid and i.indpred is null and (select array_agg(k.attnum order by k.ordinality) from unnest(i.indkey) with ordinality k(attnum,ordinality) where k.ordinality <= array_length(f.conkey,1))=f.conkey)) select count(*) from u),0::bigint,'Every M2A foreign key has a complete non-partial ordered child index.');
select is((select count(*) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace join pg_proc p on p.oid=t.tgfoid where n.nspname='app' and not t.tgisinternal and c.relname in ('academic_levels','academic_semesters','academic_modules','academic_module_aliases','instructors','instructor_brand_assignments','brand_courses','course_instructor_assignments') and p.oid='app.set_updated_at()'::regprocedure),8::bigint,'All mutable M2A tables use app.set_updated_at.');
select is((select count(*) from information_schema.role_table_grants where table_schema='app' and table_name in ('academic_levels','academic_semesters','academic_modules','academic_module_aliases','instructors','instructor_brand_assignments','brand_courses','course_instructor_assignments') and grantee in ('PUBLIC','anon','authenticated') and privilege_type in ('INSERT','UPDATE','DELETE','SELECT')),0::bigint,'Client roles have no M2A table privileges.');
select is((select count(*) from pg_policies where schemaname='app' and tablename in ('academic_levels','academic_semesters','academic_modules','academic_module_aliases','instructors','instructor_brand_assignments','brand_courses','course_instructor_assignments')),0::bigint,'M2A adds no RLS policies.');
select is((select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='app' and p.prosecdef and p.proname like '%m2a%'),0::bigint,'M2A adds no SECURITY DEFINER function.');
select * from finish();
rollback;
